CREATE TABLE journal_entries(id VARCHAR2(36) PRIMARY KEY,trip_id VARCHAR2(36) NOT NULL,owner_id VARCHAR2(36) NOT NULL,title VARCHAR2(200) NOT NULL,content CLOB NOT NULL,recap CLOB,created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,updated_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,version NUMBER(19) DEFAULT 0 NOT NULL);
CREATE INDEX journal_owner ON journal_entries(trip_id,owner_id);
CREATE TABLE journal_media(id VARCHAR2(36) PRIMARY KEY,entry_id VARCHAR2(36) NOT NULL REFERENCES journal_entries(id),object_key VARCHAR2(100) NOT NULL,mime_type VARCHAR2(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE visited_places(id VARCHAR2(36) PRIMARY KEY,trip_id VARCHAR2(36) NOT NULL,owner_id VARCHAR2(36) NOT NULL,place VARCHAR2(200) NOT NULL,visited_at TIMESTAMP WITH TIME ZONE NOT NULL,latitude NUMBER(10,7) NOT NULL,longitude NUMBER(10,7) NOT NULL);
